/* Return the const (flash) window for a given mdct_size, or NULL if there is no
 * precomputed table. Lets the decoder use the flash table directly instead of
 * copying it into a ~2 KB RAM buffer. Only 480 (44.1/48k) is negotiated today. */
const float *lhdc_get_window_const(int mdct_size)
{
    /* Match the encoder analysis window at every supported transform size.
     * Power complementarity alone does not establish encoder compatibility. */
    if (mdct_size == 480)  return LHDC_WIN_480;
    if (mdct_size == 960)  return LHDC_WIN_960;
    if (mdct_size == 1920) return LHDC_WIN_1920;
    return NULL;
}

void lhdc_gen_kbd_window(float *window, int mdct_size)
{
    int i, N = mdct_size;
    /* The encoder uses the Vorbis-style power-complementary MDCT window
     * w[n] = sin((pi/2) * sin^2((n+0.5)*pi/N))  (recovered from the reference
     * decoder's lhdc_dec_lossy_time_table_start). The synthesis window MUST match
     * the encoder's analysis window for TDAC / perfect reconstruction — the old
     * hardcoded low-overlap LHDC_WIN_480 only cleaned up tones (sparse spectra)
     * but broke TDAC on dense content, garbling real music. */
    int use_old = 0;
#if defined(LHDC_HOST_BUILD)
    { const char *e = getenv("LHDC_OLDWIN"); if (e) use_old = atoi(e); }
#endif
    if (N == 480 && use_old) {
        for (i = 0; i < 480; i++) window[i] = LHDC_WIN_480[i];
        return;
    }
    /*
     * LHDC uses a LOW-OVERLAP MDCT window (recovered from the reference decoder's
     * lhdc_dec_lossy_time_table_start): num4 zero-pad samples, a `repeating`-long
     * Vorbis sine transition, a flat 1.0 middle, a `repeating` fall, num4 zeros.
     * With 50% overlap-add this satisfies TDAC because
     *   sin^2((pi/2)sin^2(t)) + sin^2((pi/2)cos^2(t)) = 1.
     * The 48k/5ms config: N=480, repeating=96, num4 = N/4 - repeating/2 = 72.
     * (Old code used a full Vorbis/KBD window over all N -> wrong overlap structure
     * -> TDAC failed on dense/non-stationary content -> real-music garble.)
     */
    {
        int repeating, num4;
        switch (N) {
            case 480: repeating = 96;  num4 = 72;  break;   /* 48k/44.1k 5ms */
            case 960: repeating = 192; num4 = 144; break;   /* 96k 5ms (scaled x2) */
            case 1920: repeating = 384; num4 = 288; break;  /* 192k 5ms (scaled x4) */
            default:  repeating = N / 4; num4 = 0; break;   /* fallback: full 50% sine */
        }
        for (i = 0; i < N; i++) {
            if (i < num4 || i >= N - num4) {
                window[i] = 0.0f;
            } else if (i < num4 + repeating) {
                /* rising edge: vorbis sin(sin^2) over `repeating` */
                int j = i - num4;
                float s = sinf(((j + 0.5f) * ((float)M_PI / 2.0f)) / (float)repeating);
                window[i] = sinf(((float)M_PI / 2.0f) * s * s);
            } else if (i >= N - num4 - repeating) {
                /* falling edge = mirror of the rising edge (window symmetric) */
                int j = (N - 1 - i) - num4;
                float s = sinf(((j + 0.5f) * ((float)M_PI / 2.0f)) / (float)repeating);
                window[i] = sinf(((float)M_PI / 2.0f) * s * s);
            } else {
                window[i] = 1.0f;   /* flat middle */
            }
        }
    }
}

/* ================================================================
 * FAC (Fast Arithmetic Coding) Decoder
 * ================================================================ */

void lhdc_fac_dec_init(lhdc_fac_dec_t *fac, uint8_t num_symbols)
{
    fac->range = 0xFFFFFFFF;
    fac->low = 0;
    fac->num_symbols = num_symbols;
    fac->total_count = 0;
    for (int i = 0; i < num_symbols; i++) {
        fac->sym_count[i] = 1;
        fac->total_count++;
    }
}

int lhdc_fac_dec_read(lhdc_fac_dec_t *fac, lhdc_dec_bit_reader_t *br)
{
    uint32_t range = fac->range;
    uint32_t low = fac->low;
    uint32_t total = fac->total_count;
    if (total == 0) return -1;

    if (range < 0x1000000) {
        low = (low << 8) | lhdc_bit_reader_read(br, 8);
        range <<= 8;
    }

    uint32_t target = (low >> 24) & 0xFF;
    uint32_t cum = 0;
    int symbol = 0;
    for (int i = 0; i < fac->num_symbols; i++) {
        cum += fac->sym_count[i];
        if (target < (cum * 256) / total) { symbol = i; break; }
    }

    uint32_t sym_low = 0;
    for (int i = 0; i < symbol; i++) sym_low += fac->sym_count[i];
    low = low + range * sym_low / total;
    range = range * fac->sym_count[symbol] / total;
    fac->range = range;
    fac->low = low;

    fac->sym_count[symbol]++;
    fac->total_count++;

    if (fac->total_count > 16384) {
        fac->total_count = 0;
        for (int i = 0; i < fac->num_symbols; i++) {
            fac->sym_count[i] = (fac->sym_count[i] + 1) / 2;
            fac->total_count += fac->sym_count[i];
        }
    }
    return symbol;
}

